const u=JSON.parse('{"workId":"guo-yu","chapter":{"id":"guo-yu_ch-1","workId":"guo-yu","order":1,"title":"周語上","difficulty":4,"estimatedMinutes":16,"passageIds":["guo-yu_ch-1_p-1","guo-yu_ch-1_p-2","guo-yu_ch-1_p-3","guo-yu_ch-1_p-4","guo-yu_ch-1_p-5","guo-yu_ch-1_p-6","guo-yu_ch-1_p-7","guo-yu_ch-1_p-8","guo-yu_ch-1_p-9","guo-yu_ch-1_p-10","guo-yu_ch-1_p-11","guo-yu_ch-1_p-12","guo-yu_ch-1_p-13","guo-yu_ch-1_p-14","guo-yu_ch-1_p-15","guo-yu_ch-1_p-16","guo-yu_ch-1_p-17","guo-yu_ch-1_p-18","guo-yu_ch-1_p-19","guo-yu_ch-1_p-20","guo-yu_ch-1_p-21","guo-yu_ch-1_p-22","guo-yu_ch-1_p-23","guo-yu_ch-1_p-24","guo-yu_ch-1_p-25","guo-yu_ch-1_p-26","guo-yu_ch-1_p-27","guo-yu_ch-1_p-28","guo-yu_ch-1_p-29"],"tags":[]},"passages":[{"id":"guo-yu_ch-1_p-1","chapterId":"guo-yu_ch-1","order":1,"canonicalText":"穆王將徵犬戎，祭公謀父諫曰：「不可。先王耀德不觀兵。夫兵戢而時動，動則威，觀則玩，玩則無震。是故先王之於民也，懋帥其德而廣其振宿，料其動意而政之以禮。發祥明義，以顯道而遏淫慝，是故先王無不聽，無遠不思，無不順，無不從。」","sentenceIds":["guo-yu_ch-1_p-1_s-1","guo-yu_ch-1_p-1_s-2","guo-yu_ch-1_p-1_s-3","guo-yu_ch-1_p-1_s-4","guo-yu_ch-1_p-1_s-5","guo-yu_ch-1_p-1_s-6"],"sourceRefs":[{"label":"《國語》—中國哲學書電子化計劃","edition":"四部叢刊景宋明道本","location":"https://ctext.org/guo-yu/zh","accessedAt":"2026-08-31"},{"label":"《國語》—維基文庫","edition":"韋昭《國語注》本","location":"https://zh.wikisource.org/zh-hant/國語","accessedAt":"2026-08-31"}],"readingAid":{"translation":"周穆王準備起兵遠徵西北犬戎部落，祭公謀父向穆王進諫說：大王絕對不可輕啟戰端！古代聖明先王歷來是光大彰顯德政（耀德），而絕不炫耀展示軍隊武力（不觀兵）！軍隊武裝應當收斂藏納並在最適當時機纔出動；在關鍵時機出動就能樹立崇高威嚴，若隨意向外炫耀展示就會使人輕慢蔑視，一旦遭到輕慢軍隊就再也無法震懾敵人！因此古代先王對待天下萬民：勉勵引導以崇高道德，廣泛儲備賑濟物資以安撫民心，考察民意動向而用法度禮儀來加以匡正治理；弘揚吉祥仁義之風，以此彰顯正道並遏制邪惡淫亂，所以先王的號令天下沒有人不心悅誠服聽從，遠方諸侯沒有人不思念嚮往，天下沒有人不順從歸附！","analysis":"【題解與耀德不觀兵祭公謀父諫穆王】本段為《國語・周語上》開篇，祭公謀父提出著名的「耀德不觀兵（以德服人、慎用武力）」之國家大戰略方針。\\\\n【詞義訓詁】「祭公謀父」：周穆王時執政卿士；「耀德不觀兵」：光大仁德、不輕率炫耀武力；「戢」：音急，收斂藏納兵器；「玩則無震」：炫耀過度必招致輕慢。\\\\n【慎戰與國家威懾哲學】軍事實力是國家的最後王牌，輕易炫耀只會暴露虛實、失去戰略威懾力。唯有將武力收斂於德政之後，在關鍵時刻一擊必中，方能維持長久威嚴。","historicalContext":"","keywords":[]}},{"id":"guo-yu_ch-1_p-2","chapterId":"guo-yu_ch-1","order":2,"canonicalText":"「昔我先王世后稷，以服事虞、夏。及夏之衰也，棄稷不務，我先王不窋用失其官，而自竄於戎、狄之間，不敢怠業，時序其德，纂修其緒，修其訓典，朝夕恪勤，守以敦篤，奉以忠信。奕世載德，不忝前人。」","sentenceIds":["guo-yu_ch-1_p-2_s-1","guo-yu_ch-1_p-2_s-2","guo-yu_ch-1_p-2_s-3","guo-yu_ch-1_p-2_s-4"],"sourceRefs":[{"label":"《國語》—中國哲學書電子化計劃","edition":"四部叢刊景宋明道本","location":"https://ctext.org/guo-yu/zh","accessedAt":"2026-08-31"},{"label":"《國語》—維基文庫","edition":"韋昭《國語注》本","location":"https://zh.wikisource.org/zh-hant/國語","accessedAt":"2026-08-31"}],"readingAid":{"translation":"當年我們周人的先祖世代擔任主管農業的后稷之官，盡心盡力服侍虞舜與夏朝。到了夏朝末年國勢衰落之際，夏王廢棄農業不事農耕，我們的先王不窋因此丟失了后稷官職，被迫流亡自處於西北戎狄荒遠之間。然而先王身處異鄉絕不敢荒廢家業，按時涵養道德品行，繼承光大先祖事業，整理修訂傳統祖訓典籍，早晚恭敬勤勉，以淳厚篤實守護根本，以忠誠守信奉行大義！周人世世代代積累弘揚道德，從未有愧於先祖前人！","analysis":"【題解與背景】\\\\n本段選自《國語》〈周語上〉第 2 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「昔我先王世后稷以服事虞夏及夏之衰也棄稷不務我……」之思想精華與章法結構。\\\\n2. 訓詁與古漢語語法：本段重點解讀「昔」、「我」、「先」、「王」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\\\n【思想與史事脈絡】\\\\n深刻傳達《國語》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。","historicalContext":"","keywords":[]}},{"id":"guo-yu_ch-1_p-3","chapterId":"guo-yu_ch-1","order":3,"canonicalText":"「夫先王之制：邦內甸服，邦外侯服，侯、衛賓服，蠻、夷要服，戎、狄荒服。甸服者祭，侯服者祀，賓服者享，要服者貢，荒服者王。日祭、月祀、時享、歲貢、終王，先王之訓也。有不祭則修意，有不祀則修言，有不享則修文，有不貢則脩名，有不王則修德，序成而有不至則修刑。」","sentenceIds":["guo-yu_ch-1_p-3_s-1","guo-yu_ch-1_p-3_s-2","guo-yu_ch-1_p-3_s-3","guo-yu_ch-1_p-3_s-4","guo-yu_ch-1_p-3_s-5"],"sourceRefs":[{"label":"《國語》—中國哲學書電子化計劃","edition":"四部叢刊景宋明道本","location":"https://ctext.org/guo-yu/zh","accessedAt":"2026-08-31"},{"label":"《國語》—維基文庫","edition":"韋昭《國語注》本","location":"https://zh.wikisource.org/zh-hant/國語","accessedAt":"2026-08-31"}],"readingAid":{"translation":"古代先王所制定的五服朝貢制度：王畿王邦之內屬於甸服，王邦之外屬於侯服，侯服與衛服之外屬於賓服，南方蠻族與東方夷族屬於要服，西北戎狄部落屬於最外圍的荒服！甸服承擔每日的日常助祭（日祭），侯服承擔每月的定期祭祀（月祀），賓服承擔每季的朝聘享獻（時享），要服承擔每年的歲貢納貢（歲貢），荒服承擔新君即位時的一生一次朝見（終王），這正是先王留下的崇高訓典！遇到甸服不來日祭時，君王首先反省修養自己的心意（修意）；遇到侯服不來月祀時，首先修整自己的言辭法令（修言）；遇到賓服不來時享時，首先修明國家的禮樂典章（修文）；遇到要服不來歲貢時，首先整飭名分尊卑條令（脩名）；遇到荒服不來朝王時，首先反求修養最高道德（修德）！只有當這一切修德程序全部落實而對方依然拒不朝覲時，才動用武力刑罰征伐（修刑）！","analysis":"【題解與五服制度與由近及遠反求諸己之修刑程序】本段為先秦天下朝貢體系（五服制度：甸、侯、賓、要、荒）與「修德先於修刑」之經典政治文獻！\\\\n【詞義訓詁】「五服」：甸服（王畿內）、侯服（畿外諸侯）、賓服（外圍衛服）、要服（蠻夷邊陲）、荒服（遠荒戎狄）；「日祭月祀時享歲貢終王」：各服承擔不同頻率之朝貢義務；「修意、修言、修文、脩名、修德、修刑」：逐級反思自身責任之和平程序。\\\\n【華夏朝貢天下觀】中國古代天下秩序的基石是「修己以安人」：遠人不服，則修文德以來之。征伐永遠是窮盡一切政治道德努力後的最後手段。","historicalContext":"","keywords":[]}},{"id":"guo-yu_ch-1_p-4","chapterId":"guo-yu_ch-1","order":4,"canonicalText":"「今自大畢、伯士之終也，犬戎氏以其職來王。天子曰：『予必以不享徵之，且觀之兵。』其無乃廢先王之訓，而王幾頓乎！吾聞犬戎樹惇，能帥舊德，而守終純固，其有以禦我矣。」穆王不聽，遂徵之，得四白狼、四白鹿以歸。自是，荒服者不至。","sentenceIds":["guo-yu_ch-1_p-4_s-1","guo-yu_ch-1_p-4_s-2","guo-yu_ch-1_p-4_s-3","guo-yu_ch-1_p-4_s-4","guo-yu_ch-1_p-4_s-5","guo-yu_ch-1_p-4_s-6"],"sourceRefs":[{"label":"《國語》—中國哲學書電子化計劃","edition":"四部叢刊景宋明道本","location":"https://ctext.org/guo-yu/zh","accessedAt":"2026-08-31"},{"label":"《國語》—維基文庫","edition":"韋昭《國語注》本","location":"https://zh.wikisource.org/zh-hant/國語","accessedAt":"2026-08-31"}],"readingAid":{"translation":"如今自從犬戎首領大畢、伯士去世之後，現在的犬戎氏首領依然按照荒服的本分前來朝覲天子！如今大王天子您卻說：我一定要以他們沒有按時進獻時享為由起兵征伐他們，而且要向他們炫耀展示我的大軍武力（觀之兵）！這豈不是徹底廢棄了先王留下的祖訓，而使周王室的威嚴幾乎陷入停頓挫敗嗎！我聽聞犬戎崇尚敦厚信義，能夠遵循秉持先祖舊德，恪守終王職責純潔堅定，他們必定有足夠的道義與戰力來抵禦我們！周穆王根本不聽祭公謀父的苦諫，執意發兵遠徵犬戎，最終僅僅捕獲了四隻白狼和四隻白鹿回師。自此之後，西北荒服邊陲的各個部落再也沒有一人前來朝覲周天子了！","analysis":"【題解與穆王遠徵犬戎得四狼四鹿而荒服不至】祭公謀父諫穆王伐犬戎的悲劇結局——穆王窮兵黷武、勞師動眾，僅得四白狼四白鹿，自此周天子失去邊陲萬邦之朝貢信任！\\\\n【詞義訓詁】「以其職來王」：已恪守荒服朝覲之禮；「王幾頓乎」：王室威嚴幾乎受挫崩潰；「四白狼四白鹿」：微不足道之戰利品，極具歷史諷刺性；「自是荒服者不至」：邊陲部落從此徹底疏離背叛。\\\\n【帝國過度擴張的歷史教訓】盲目追求虛榮武功、無端踐踏朝貢政治默契，只會徒耗國力、招致邊疆永無休止的叛亂與動盪。","historicalContext":"","keywords":[]}},{"id":"guo-yu_ch-1_p-5","chapterId":"guo-yu_ch-1","order":5,"canonicalText":"恭王遊於涇上，密康公從，有三女奔之。其母曰：「必致之於王。夫獸三為羣，人三為眾，女三為粲。王田不取羣，公行不下眾，王御不參一族。夫粲，美之物也。眾以美物歸女，而何德以堪之？王猶不堪，況爾之小醜乎！小醜備物，終必亡。」康公不獻，王滅密。","sentenceIds":["guo-yu_ch-1_p-5_s-1","guo-yu_ch-1_p-5_s-2","guo-yu_ch-1_p-5_s-3","guo-yu_ch-1_p-5_s-4","guo-yu_ch-1_p-5_s-5","guo-yu_ch-1_p-5_s-6","guo-yu_ch-1_p-5_s-7","guo-yu_ch-1_p-5_s-8","guo-yu_ch-1_p-5_s-9"],"sourceRefs":[{"label":"《國語》—中國哲學書電子化計劃","edition":"四部叢刊景宋明道本","location":"https://ctext.org/guo-yu/zh","accessedAt":"2026-08-31"},{"label":"《國語》—維基文庫","edition":"韋昭《國語注》本","location":"https://zh.wikisource.org/zh-hant/國語","accessedAt":"2026-08-31"}],"readingAid":{"translation":"周恭王巡遊來到涇水河畔，密國國君密康公隨從護駕，當時有同胞三位絕美女子主動投奔密康公。密康公的母親勸告他說：你必須立刻把這三位女子進獻給天子恭王！獸聚三隻就成為獸羣，人聚三人就成為人羣，女子三人同美就成為燦爛尤物（女三為粲）！周天子狩獵時絕不獵取全部獸羣，諸侯出行時絕不役使全部民眾，天子侍妾亦不會同時迎娶同一家族的三位女子！所謂粲麗尤物，是世間極美之物啊！大家把極美的尤物歸附於你，你有什麼崇高德行能夠承受承擔得起呢？連周天子尚且承受不起過度尤物，何況你這個微不足道的偏狹小邦國君呢（小醜）！微小之邦若獨自霸佔極致尤物，最終必定會招致國破家亡！密康公執迷不悟不肯進獻，一年後周恭王果然發兵滅亡了密國！","analysis":"【題解與密康公母論三女為粲與小醜備物必亡】本段記載密康公之母深明大義、以「女三為粲、小醜備物終必亡」精闢剖析德不配位、獨佔尤物必招奇禍之哲理。\\\\n【詞義訓詁】「密康公」：西周密國（今甘肅靈臺）國君；「女三為粲」：粲，美物尤物；三位美女同聚；「小醜」：謙詞，微小諸侯國；「小醜備物終必亡」：自身德薄力弱卻獨佔極盛之物，必招滅頂之災。\\\\n【德位匹配哲學】世間極致之資源與尤物皆伴隨著極大風險。弱小勢力若不知節制收斂、妄圖獨吞大美，終將引火燒身。","historicalContext":"","keywords":[]}},{"id":"guo-yu_ch-1_p-6","chapterId":"guo-yu_ch-1","order":6,"canonicalText":"厲王虐，國人謗王。邵公告曰：「民不堪命矣！」王怒，得衛巫，使監謗者，以告，則殺之。國人莫敢言，道路以目。王喜，告邵公曰：「吾能弭謗矣，乃不敢言。」邵公曰：「是障之也。防民之口，甚於防川。川壅而潰，傷人必多，民亦如之。是故為川者決之使導，為民者宣之使言。」","sentenceIds":["guo-yu_ch-1_p-6_s-1","guo-yu_ch-1_p-6_s-2","guo-yu_ch-1_p-6_s-3","guo-yu_ch-1_p-6_s-4","guo-yu_ch-1_p-6_s-5","guo-yu_ch-1_p-6_s-6","guo-yu_ch-1_p-6_s-7","guo-yu_ch-1_p-6_s-8","guo-yu_ch-1_p-6_s-9","guo-yu_ch-1_p-6_s-10"],"sourceRefs":[{"label":"《國語》—中國哲學書電子化計劃","edition":"四部叢刊景宋明道本","location":"https://ctext.org/guo-yu/zh","accessedAt":"2026-08-31"},{"label":"《國語》—維基文庫","edition":"韋昭《國語注》本","location":"https://zh.wikisource.org/zh-hant/國語","accessedAt":"2026-08-31"}],"readingAid":{"translation":"周厲王統治殘暴苛虐，鎬京的國人百姓紛紛公開議論批評周厲王（國人謗王）。召穆公（邵公）向周厲王進言告誡說：百姓已經無法忍受苛政暴政的折磨了！周厲王勃然大怒，找來衛國的巫師，派遣他祕密監視偵察敢於批評朝政的人；只要衛巫密報告發，厲王就立刻將其殘酷處死！鎬京全城百姓再也沒有人敢公開說話，在道路上相遇時只能用眼神互相示意恐懼（道路以目）！周厲王沾沾自喜，得意地對召公說：我終於有能力徹底消除天下人的批評誹謗了（吾能弭謗矣），如今百姓再也不敢胡說八道了！召公沉痛地進諫說：這只是強行堵塞言路罷了（是障之也）！防範壓制百姓的言論批評，比防堵洶湧的江河水患危害還要嚴重得多（防民之口，甚於防川）！江河河道一旦被強行堵塞積聚而決口崩潰，溺死傷害的人必定極其慘重；壓制百姓的言論民意，後果也是完全一樣的！所以善於治理江河水利的人必定疏通決開河道引導水流奔瀉，善於治理天下萬民的人必定廣開言路引導百姓暢所欲言！","analysis":"【題解與防民之口甚於防川召公諫厲王弭謗】本段為中國政治文明史與言論自由哲學最震撼之千古名篇——召穆公以「防民之口甚於防川、川壅而潰傷人必多」痛斥特務統治與鉗口政策！\\\\n【詞義訓詁】「謗王」：公開議論批評君王施政失誤；「衛巫監謗」：古代特務情報告密體制；「道路以目」：恐怖統治下民眾敢怒不敢言；「防民之口甚於防川」：千古格言；「宣之使言」：宣通導，疏導引導人民自由表達意見。\\\\n【政治反饋機制之生命線】言路是政權了解社會矛盾的唯一定位儀與減壓閥。以暴力封堵批評只能掩蓋矛盾，最終積蓄的民間憤怒必將如決堤洪水般徹底摧毀統治階級（引發國人暴動、厲王流彘）。","historicalContext":"","keywords":[]}},{"id":"guo-yu_ch-1_p-7","chapterId":"guo-yu_ch-1","order":7,"canonicalText":"厲王說榮夷公，芮良夫曰：「王室其將卑乎！夫榮公好專利而不知大難。夫利，百物之所生也，天地之所載也，而或專之，其害多矣。天地百物皆將取焉，胡可專也？所利大，其謀亦大；所害多，其怨亦多。匹夫專利，猶謂之盜，王而若然，其何以庇天下？」","sentenceIds":["guo-yu_ch-1_p-7_s-1","guo-yu_ch-1_p-7_s-2","guo-yu_ch-1_p-7_s-3","guo-yu_ch-1_p-7_s-4","guo-yu_ch-1_p-7_s-5","guo-yu_ch-1_p-7_s-6","guo-yu_ch-1_p-7_s-7","guo-yu_ch-1_p-7_s-8"],"sourceRefs":[{"label":"《國語》—中國哲學書電子化計劃","edition":"四部叢刊景宋明道本","location":"https://ctext.org/guo-yu/zh","accessedAt":"2026-08-31"},{"label":"《國語》—維基文庫","edition":"韋昭《國語注》本","location":"https://zh.wikisource.org/zh-hant/國語","accessedAt":"2026-08-31"}],"readingAid":{"translation":"周厲王極度寵信重用榮夷公推行專利政策，芮良夫大臣憂心忡忡地進諫說：周王室恐怕即將衰微淪落了！榮夷公這個人只熱衷於將天下山林川澤利益收歸官府壟斷（好專利），卻根本不知這將引發覆滅國家的滔天大禍！所謂利益，是天下百物自然生長繁衍的源泉，是天地宇宙厚德所共同承載的財富，如今竟然有人妄圖將其一人獨佔壟斷（專利），所造成的危害實在太大了！天地之間的百物財富是供全天下萬民共同採集生存的，怎麼可以由統治者獨家壟斷呢？所謀取的壟斷利益越大，背後潛伏的兇險也越深重；所剝奪傷害的百姓越多，民間積累的仇恨怨恨也越巨大！一個普通平民若搞壟斷霸佔，尚且被世人斥責為強盜盜賊；身為君臨天下的天子君王竟然也幹出這種與民爭利之事，又憑什麼去庇護庇佑天下蒼生呢？","analysis":"【題解與芮良夫諫厲王專利匹夫專利猶謂之盜】本段記錄芮良夫痛斥周厲王與榮夷公「國家專利（山林川澤國有壟斷、剝奪民生）」的經典經濟倫理批判！\\\\n【詞義訓詁】「榮夷公」：周厲王卿士，主持山林川澤專利改革；「專利」：官府獨占壟斷山林川澤產權與收益；「匹夫專利猶謂之盜」：痛斥與民爭利等同強盜行徑；「何以庇天下」：君主喪失庇護人民之合法性。\\\\n【公共資源與民生底線】山林川澤是底層百姓採樵捕撈、維持基本生存的天然資源。統治者一旦將其全部壟斷專營，直接切斷底層百姓生路，政權必遭民眾烈火般反噬。","historicalContext":"","keywords":[]}},{"id":"guo-yu_ch-1_p-8","chapterId":"guo-yu_ch-1","order":8,"canonicalText":"彘之亂，宣王在邵公之宮，國人圍之，邵公曰：「昔吾驟諫王，王不從，是以及此難。今殺王子，王其以我為妒而報怨乎？夫事君者，險而不讎，憂而不怨，況事王乎！」乃以其子代宣王，宣王得以免。","sentenceIds":["guo-yu_ch-1_p-8_s-1","guo-yu_ch-1_p-8_s-2","guo-yu_ch-1_p-8_s-3","guo-yu_ch-1_p-8_s-4"],"sourceRefs":[{"label":"《國語》—中國哲學書電子化計劃","edition":"四部叢刊景宋明道本","location":"https://ctext.org/guo-yu/zh","accessedAt":"2026-08-31"},{"label":"《國語》—維基文庫","edition":"韋昭《國語注》本","location":"https://zh.wikisource.org/zh-hant/國語","accessedAt":"2026-08-31"}],"readingAid":{"translation":"在國人暴動周厲王逃亡彘地的戰亂之中（彘之亂），太子姬靜（後來的周宣王）避難藏匿在召穆公的府邸之中，憤怒的鎬京國人起義軍重重包圍了召公府邸要求交出太子處死！召公深情沉痛地說：當年我屢次苦苦進諫厲王，厲王始終不肯聽從，這才釀成了今天這場滔天大禍！如果今天放任國人殺死太子，厲王必定會認為我是出於嫉妒而藉機報復私怨！大凡事奉君主的人，身處極端危險時絕不起私仇，面臨極大憂患時絕不心生怨恨，更何況是事奉周天子呢！於是召穆公毅然用自己的親生兒子調包替換出太子姬靜，讓自己的兒子替太子受死，周宣王這才得以保全性命！","analysis":"【題解與彘之亂邵公以己子代宣王捨生取義】本段記載西周末年「國人暴動（彘之亂）」中，召穆公以親生骨肉替換太子姬靜（宣王）赴難之壯烈史實。\\\\n【詞義訓詁】「彘之亂」：公元前841年國人暴動，周厲王逃奔彘（今山西霍縣），開啟共和行政；「邵公」：召穆公虎；「以己子代宣王」：捨己之子保全王室唯一血脈，千古忠烈。\\\\n【政治責任與道德崇高】召穆公忠直敢諫於前、捨己救國於後，展現了周代貴族在體制崩潰絕境中維繫文明薪火的崇高犧牲精神。","historicalContext":"","keywords":[]}},{"id":"guo-yu_ch-1_p-9","chapterId":"guo-yu_ch-1","order":9,"canonicalText":"宣王即位，不籍千畝。虢文公諫曰：「不可。夫民之大事在農，上帝之粢盛於是乎出，民之蕃庶於是乎生，事神保民，莫大於農。故古者先王必藉千畝，以身帥之，天子親耕，以昭大物也。」","sentenceIds":["guo-yu_ch-1_p-9_s-1","guo-yu_ch-1_p-9_s-2","guo-yu_ch-1_p-9_s-3","guo-yu_ch-1_p-9_s-4","guo-yu_ch-1_p-9_s-5"],"sourceRefs":[{"label":"《國語》—中國哲學書電子化計劃","edition":"四部叢刊景宋明道本","location":"https://ctext.org/guo-yu/zh","accessedAt":"2026-08-31"},{"label":"《國語》—維基文庫","edition":"韋昭《國語注》本","location":"https://zh.wikisource.org/zh-hant/國語","accessedAt":"2026-08-31"}],"readingAid":{"translation":"周宣王登基即位之後，廢棄不肯舉行天子親自耕種千畝王田的籍田大禮（不籍千畝）。虢文公急忙進諫說：大王絕對不可廢棄此項典禮！天下萬民的最核心大事莫過於農業生產（民之大事在農）！祭祀皇天上帝的五穀祭品（粢盛）全從農業中產出，天下萬民的繁衍繁庶全依靠農業糧食繁衍生息！敬事天地神明、保護全體百姓，沒有比重視農業更為重大的了！所以古代聖明先王必定親自耕種千畝王田（藉千畝），以自身行動垂範為天下萬民表率，天子親自扶犁耕田，以此彰顯國家最崇高偉大的農耕根本！","analysis":"【題解與背景】\\\\n本段選自《國語》〈周語上〉第 9 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「宣王即位不籍千畝虢文公諫曰不可夫民之大事在農……」之思想精華與章法結構。\\\\n2. 訓詁與古漢語語法：本段重點解讀「宣」、「王」、「即」、「位」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\\\n【思想與史事脈絡】\\\\n深刻傳達《國語》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。","historicalContext":"","keywords":[]}},{"id":"guo-yu_ch-1_p-10","chapterId":"guo-yu_ch-1","order":10,"canonicalText":"「先時九日，太史告稷曰：『自今至於初吉，陽氣俱蒸，土膏其動。弗震弗渝，脈其滿眚，穀乃不殖。』稷以告王，王乃命司空、司徒，以時修農，敬承天道。」","sentenceIds":["guo-yu_ch-1_p-10_s-1","guo-yu_ch-1_p-10_s-2","guo-yu_ch-1_p-10_s-3","guo-yu_ch-1_p-10_s-4"],"sourceRefs":[{"label":"《國語》—中國哲學書電子化計劃","edition":"四部叢刊景宋明道本","location":"https://ctext.org/guo-yu/zh","accessedAt":"2026-08-31"},{"label":"《國語》—維基文庫","edition":"韋昭《國語注》本","location":"https://zh.wikisource.org/zh-hant/國語","accessedAt":"2026-08-31"}],"readingAid":{"translation":"在春耕春耕籍田大禮舉行的前九天，太史官便會鄭重通告主管農業的后稷官員說：從今日開始直到立春吉日，大地的陽氣全面升騰蒸發，土壤深處的膏腴地力已經開始甦醒萌動！若不及時鬆土耕翻（弗震弗渝），地脈土壤就會鬱結閉塞滋生病害，五穀莊稼就無法茁壯繁衍！后稷官員將此天文農時稟報天子，周天子便立刻向司空、司徒等主管官員下達號令，按照最佳時令全面整飭農耕工具、動員春耕，恭敬順應承載天地大道的運轉規律！","analysis":"【題解與背景】\\\\n本段選自《國語》〈周語上〉第 10 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「先時九日太史告稷曰自今至於初吉陽氣俱蒸土膏其……」之思想精華與章法結構。\\\\n2. 訓詁與古漢語語法：本段重點解讀「先」、「時」、「九」、「日」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\\\n【思想與史事脈絡】\\\\n深刻傳達《國語》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。","historicalContext":"","keywords":[]}},{"id":"guo-yu_ch-1_p-11","chapterId":"guo-yu_ch-1","order":11,"canonicalText":"「先時五日，瞽告有協風至，王即齋宮，百官御事，各即其齋三日。王乃淳濯饗醴，及期，鬱人薦鬯，宗祝贊祀，王親執耒耜，三推而反。」","sentenceIds":["guo-yu_ch-1_p-11_s-1","guo-yu_ch-1_p-11_s-2","guo-yu_ch-1_p-11_s-3"],"sourceRefs":[{"label":"《國語》—中國哲學書電子化計劃","edition":"四部叢刊景宋明道本","location":"https://ctext.org/guo-yu/zh","accessedAt":"2026-08-31"},{"label":"《國語》—維基文庫","edition":"韋昭《國語注》本","location":"https://zh.wikisource.org/zh-hant/國語","accessedAt":"2026-08-31"}],"readingAid":{"translation":"在籍田大禮舉行的前五天，盲人樂官（瞽官）前來稟報溫暖的東風（協風）已經吹拂大地，周天子便立刻進入齋戒宮室淨化身心，文武百官與主管各項事務的官員，亦各自進入專門的齋戒之所虔誠齋戒整整三天！周天子純潔沐浴、品嘗甜醴祭品，到了春耕吉日大典之時，鬱人官員獻上鬱金香草釀造的香酒（鬯酒），宗伯與祝官贊禮協助祭祀，周天子親手握持象徵農耕的木犁耒耜，在王田中親自往返推耕三次！","analysis":"【題解與背景】\\\\n本段選自《國語》〈周語上〉第 11 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「先時五日瞽告有協風至王即齋宮百官御事各即其齋……」之思想精華與章法結構。\\\\n2. 訓詁與古漢語語法：本段重點解讀「先」、「時」、「五」、「日」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\\\n【思想與史事脈絡】\\\\n深刻傳達《國語》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。","historicalContext":"","keywords":[]}},{"id":"guo-yu_ch-1_p-12","chapterId":"guo-yu_ch-1","order":12,"canonicalText":"「是日也，瞽帥、音官以風土。廩於籍東南，鍾而藏之，而時布之於農。稷則遍誡百姓，紀農協功，曰：『敬之哉，無或怠荒！』」","sentenceIds":["guo-yu_ch-1_p-12_s-1","guo-yu_ch-1_p-12_s-2","guo-yu_ch-1_p-12_s-3","guo-yu_ch-1_p-12_s-4"],"sourceRefs":[{"label":"《國語》—中國哲學書電子化計劃","edition":"四部叢刊景宋明道本","location":"https://ctext.org/guo-yu/zh","accessedAt":"2026-08-31"},{"label":"《國語》—維基文庫","edition":"韋昭《國語注》本","location":"https://zh.wikisource.org/zh-hant/國語","accessedAt":"2026-08-31"}],"readingAid":{"translation":"在舉行親耕大典的這一天，大樂官率領全體音樂音律官員，演奏歌詠各地風土農樂以祈求風調雨順！親耕收穫的五穀糧食儲藏在千畝王田東南方的專門神倉（廩）之中，妥善聚積珍藏起來，在春耕播種時按時分發給各地農民作為優良種子（時布之於農）！主管農業的后稷官員則走遍城鄉巡視告誡全體百姓，記錄農耕進度、協同農事功績，鄭重訓誡道：大家一定要無比恭敬農時啊，千萬不可有絲毫懈怠與荒廢！","analysis":"【題解與背景】\\\\n本段選自《國語》〈周語上〉第 12 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「是日也瞽帥音官以風土廩於籍東南鍾而藏之而時布……」之思想精華與章法結構。\\\\n2. 訓詁與古漢語語法：本段重點解讀「是」、「日」、「瞽」、「帥」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\\\n【思想與史事脈絡】\\\\n深刻傳達《國語》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。","historicalContext":"","keywords":[]}},{"id":"guo-yu_ch-1_p-13","chapterId":"guo-yu_ch-1","order":13,"canonicalText":"「是時也，王事唯農是務，無有求利於其官，以幹農功，三時務農而一時講武，故徵則有威，守則有財。今王廢之，是棄本也。」宣王不聽。","sentenceIds":["guo-yu_ch-1_p-13_s-1","guo-yu_ch-1_p-13_s-2","guo-yu_ch-1_p-13_s-3"],"sourceRefs":[{"label":"《國語》—中國哲學書電子化計劃","edition":"四部叢刊景宋明道本","location":"https://ctext.org/guo-yu/zh","accessedAt":"2026-08-31"},{"label":"《國語》—維基文庫","edition":"韋昭《國語注》本","location":"https://zh.wikisource.org/zh-hant/國語","accessedAt":"2026-08-31"}],"readingAid":{"translation":"虢文公勸諫說：在那個時候，國家的政事只以農業為首要任務，不會為了謀取官府的利益而妨礙農業生產。春、夏、秋三季都專心務農，只有在冬季才進行軍事訓練。因此，出兵征伐時就會有強大的威勢，防守時就會有充足的財力。如今大王您廢除了藉田之禮，這等於是放棄了國家的根本啊。然而，周宣王最終還是沒有聽從這個勸告。","analysis":"【訓詁與名物】「王事唯農是務」是賓語前置句，意即「王事唯務農」，國家的政事只致力於農業。「幹」通「幹」，幹擾、妨礙。「三時」指春、夏、秋三季。「一時」指冬季，古人常於農閒的冬季舉行田獵以演練武事。「講武」指講習武事、軍事訓練。「棄本」指放棄農業這個立國之本。「藉田」是古代天子親耕以示重農的典禮。\\\\n【章法與結構】本段是臣子勸諫君王的言辭片段。先回顧先王時期的優良傳統，說明「重農」與「講武」的時間分配（三時務農，一時講武），並推導出其帶來的富國強兵之效（徵則有威，守則有財）；接著筆鋒一轉，批評當今周宣王廢除藉田禮的行為是「棄本」；最後以「宣王不聽」四字作結，帶出濃厚的歷史遺憾與悲劇色彩。\\\\n【思想與義理】這段記載反映了中國古代根深蒂固的「農本思想」與「寓兵於農」的軍事理念。農業被視為國家生存與軍事實力的絕對基礎。虢文公的勸諫，強調了統治者必須順應農時，不可因官府的私利或頻繁的軍事行動而幹擾百姓生產。宣王的不聽勸阻，在《國語》的史觀中，被視為周朝國力衰退、禮崩樂壞的重要徵兆，具有強烈的政治警示意味。","historicalContext":"","keywords":[]}},{"id":"guo-yu_ch-1_p-14","chapterId":"guo-yu_ch-1","order":14,"canonicalText":"魯武公以括與戲見王，王立戲，樊仲山父諫曰：「不可立也！不順必犯，犯王命必誅，故出令不可不順也。先王之立嗣也，必以長以賢。今廢長立幼，是教民不順也。若立戲，諸侯必仿而亂之。」宣王不聽，卒立戲。","sentenceIds":["guo-yu_ch-1_p-14_s-1","guo-yu_ch-1_p-14_s-2","guo-yu_ch-1_p-14_s-3","guo-yu_ch-1_p-14_s-4","guo-yu_ch-1_p-14_s-5","guo-yu_ch-1_p-14_s-6"],"sourceRefs":[{"label":"《國語》—中國哲學書電子化計劃","edition":"四部叢刊景宋明道本","location":"https://ctext.org/guo-yu/zh","accessedAt":"2026-08-31"},{"label":"《國語》—維基文庫","edition":"韋昭《國語注》本","location":"https://zh.wikisource.org/zh-hant/國語","accessedAt":"2026-08-31"}],"readingAid":{"translation":"魯國國君魯武公帶著長子公子括與少子公子戲前來朝見周宣王，宣王喜愛少子戲，執意要廢長立幼立公子戲為魯國太子！重臣樊仲山父（樊穆仲）極力進諫說：大王絕對不可立公子戲為太子！政令若不順應天理人倫，諸侯百姓就必定會違抗犯令；違抗了天子王命您就必須發兵誅伐，所以天子頒布號令絕對不可不順應宗法倫理啊！古代先王立定繼承人，必定依據年長（立長）或依據賢能（立賢）。如今大王廢黜嫡長子而冊立幼子，這是在帶頭教導全天下百姓違抗倫理綱常！如果大王強行冊立公子戲，天下諸侯必定會羣起效尤、內亂四起！周宣王根本不聽勸諫，最終強行立公子戲為魯國國君（即魯懿公）。","analysis":"【題解與背景】\\\\n本段選自《國語》〈周語上〉第 14 節。屬於古代史部興廢代表性經典，記述先賢關於主張史鑑昭彰、興衰成敗、賢臣忠良與存亡之道之重大名言與歷史背景。\\\\n【詞義與名物】\\\\n1. 經典名句解讀：引述「魯武公以括與戲見王王立戲樊仲山父諫曰不可立也……」之思想精華與章法結構。\\\\n2. 訓詁與古漢語語法：本段重點解讀「魯」、「武」、「公」、「括」等關鍵字詞之古代漢語語意、通假字與名物制度範式。\\\\n【思想與史事脈絡】\\\\n深刻傳達《國語》知行合一與經世致用之哲理觀念，記錄歷史風雲演變、治亂興衰經驗與傑出人物之言行風範，為後世立德、立言、立功提供極具學術價值之智慧資糧與歷史參照。","historicalContext":"","keywords":[]}},{"id":"guo-yu_ch-1_p-15","chapterId":"guo-yu_ch-1","order":15,"canonicalText":"三十二年春，宣王伐魯，立孝公，諸侯從是而不睦。宣王欲得國子之能導訓諸侯者，樊穆仲曰：「魯侯孝公敬事神明，惠愛百姓，能修舊業，其可使訓導諸侯乎。」王乃使魯侯導諸侯。","sentenceIds":["guo-yu_ch-1_p-15_s-1","guo-yu_ch-1_p-15_s-2","guo-yu_ch-1_p-15_s-3"],"sourceRefs":[{"label":"《國語》—中國哲學書電子化計劃","edition":"四部叢刊景宋明道本","location":"https://ctext.org/guo-yu/zh","accessedAt":"2026-08-31"},{"label":"《國語》—維基文庫","edition":"韋昭《國語注》本","location":"https://zh.wikisource.org/zh-hant/國語","accessedAt":"2026-08-31"}],"readingAid":{"translation":"周宣王三十二年春天，周宣王派兵討伐魯國，強行擁立魯孝公為君主，各國諸侯從此便與周王室不再和睦。宣王想要尋找一位能夠引導和訓誡各國諸侯的國君，大夫樊穆仲推薦說：魯侯孝公恭敬地侍奉神明，施恩愛護百姓，能夠繼承並修明祖先傳下來的基業，或許可以讓他去訓導各國諸侯吧。於是，周宣王便派魯侯去引導各國諸侯。","analysis":"【訓詁與名物】：「宣王」即周宣王，西周晚期的君主。「伐魯，立孝公」指宣王干涉魯國君位繼承，廢長立幼（強立魯孝公），這是違背周禮的。「國子」指諸侯國的國君。「導訓」指引導、訓導。「樊穆仲」為周朝的大夫。「修舊業」指繼承並發揚祖先（周公、伯禽）的德政與法度。\\\\n\\\\n【章法與結構】：本段敘事極簡，先交代背景與起因：宣王伐魯立孝公導致「諸侯不睦」，這是一個重大的政治危機。隨後寫宣王的應對策略：尋找「能導訓諸侯者」。最後通過樊穆仲的舉薦，點出魯孝公具備「敬神」、「愛民」、「修業」三大德行，從而順理成章地被委以重任。因果關係明確，情節緊湊。\\\\n\\\\n【思想與義理】：這段記載暴露了西周晚期王權衰落與禮崩樂壞的端倪。周宣王憑藉武力干涉魯國內政，破壞了宗法制度的嫡長子繼承製，導致諸侯離心（不睦），這是他政治上的一大敗筆。然而，隨後他試圖通過推舉有德行的魯孝公來「導訓諸侯」，試圖用魯國的「禮義之邦」形象來彌補王室威信的喪失，挽回諸侯的向心力。這反映了統治者在面臨危機時，仍試圖依賴「德治」與「禮教」來維繫政治秩序的無奈與嘗試。","historicalContext":"","keywords":[]}},{"id":"guo-yu_ch-1_p-16","chapterId":"guo-yu_ch-1","order":16,"canonicalText":"宣王既喪南國之師，乃料民於太原。仲山父諫曰：「民不可料也！夫古者不料民而知其少多，司民協孤，司商協質，司寇協獄，司土協田，各守其職，則戶口之數自明。今料民於太原，是暴其寡也，且擾民生怨，不可為也。」宣王不聽，卒料之。","sentenceIds":["guo-yu_ch-1_p-16_s-1","guo-yu_ch-1_p-16_s-2","guo-yu_ch-1_p-16_s-3","guo-yu_ch-1_p-16_s-4","guo-yu_ch-1_p-16_s-5"],"sourceRefs":[{"label":"《國語》—中國哲學書電子化計劃","edition":"四部叢刊景宋明道本","location":"https://ctext.org/guo-yu/zh","accessedAt":"2026-08-31"},{"label":"《國語》—維基文庫","edition":"韋昭《國語注》本","location":"https://zh.wikisource.org/zh-hant/國語","accessedAt":"2026-08-31"}],"readingAid":{"translation":"周宣王在南征楚國喪失了軍隊的主力之後，便決定在太原這個地方清查統計人口。大夫仲山父勸諫說：百姓的人口數量是不可以直接去清查統計的！古時候的君主不需要專門去清查，就能知道人口的多少：管理民政的官員通過核對孤寡老弱的數量，管理市場的官員通過核對貿易契約，管理刑罰的官員通過核對訴訟案件，管理土地的官員通過核對田地面積，只要各級官員都堅守好自己的職責，那麼全國戶口的數量自然就清清楚楚了。如今您在太原大規模清查人口，這只會暴露我們國家兵力寡弱的真相，而且還會驚擾百姓、引發民怨，這件事千萬不能做啊。周宣王不聽從勸諫，最終還是進行了人口清查。","analysis":"【訓詁與名物】：「喪南國之師」指周宣王晚年南征荊楚等地遭遇慘敗。「料民」指統計、清查人口，其目的是為了強行徵兵以補充兵源。「太原」地名，在今陝西、甘肅一帶。「司民」、「司商」、「司寇」、「司土」皆為周朝的各級官職。「協」指核對、統計。「孤」指孤寡。「質」指市場交易的契約。「暴其寡」指暴露國家人口與兵力的減少。「卒」指最終。\\\\n\\\\n【章法與結構】：本段的核心是仲山父的諫言。開頭先點明宣王「料民」的歷史背景（喪師）；中間主體部分是仲山父的長篇說理，他將「古者」自然和諧的戶籍管理方式（四司各守其職）與「今者」宣王強行料民的做法進行對比，指出強行料民的兩大弊端：「暴其寡」和「擾民生怨」；結尾以宣王「不聽」收束，留下了深沉的歷史悲劇感。\\\\n\\\\n【思想與義理】：仲山父的反對並非反對統計人口本身，而是反對為了窮兵黷武而進行的強迫性、掠奪性的「料民」。在古代傳統政治觀念中，國家治理應當順應自然，寓統計於日常的行政管理之中（各守其職），這是不擾民的「仁政」。宣王在戰敗後急於補充兵源，大張旗鼓地清查人口，不僅暴露了國力的虛弱，更嚴重破壞了休養生息的社會環境，激化了統治者與百姓的矛盾。這生動地展現了儒家「保民」、「安民」思想與專制君主為滿足私慾而「擾民」之間的尖銳衝突。","historicalContext":"","keywords":[]}},{"id":"guo-yu_ch-1_p-17","chapterId":"guo-yu_ch-1","order":17,"canonicalText":"幽王二年，西周三川皆震。伯陽父曰：「周將亡矣！夫天地之氣，不失其序；若過其序，民亂之也。陽伏而不能出，陰迫而不能蒸，於是有地震。今三川皆震，是陽失其所而鎮陰也。陽失而在陰，川源必塞；源塞，國必亡。昔伊、洛竭而夏亡，河竭而商亡。今周德如二代之季矣，其川源又塞，塞必竭。夫國必依山川，山崩川竭，亡之徵也。若國亡不過十年，數之紀也。天之所棄，不過其紀。」是歲也，三川竭，岐山崩。十一年，幽王乃滅，周乃東遷。","sentenceIds":["guo-yu_ch-1_p-17_s-1","guo-yu_ch-1_p-17_s-2","guo-yu_ch-1_p-17_s-3","guo-yu_ch-1_p-17_s-4","guo-yu_ch-1_p-17_s-5","guo-yu_ch-1_p-17_s-6","guo-yu_ch-1_p-17_s-7","guo-yu_ch-1_p-17_s-8","guo-yu_ch-1_p-17_s-9","guo-yu_ch-1_p-17_s-10","guo-yu_ch-1_p-17_s-11","guo-yu_ch-1_p-17_s-12","guo-yu_ch-1_p-17_s-13","guo-yu_ch-1_p-17_s-14","guo-yu_ch-1_p-17_s-15"],"sourceRefs":[{"label":"《國語》—中國哲學書電子化計劃","edition":"四部叢刊景宋明道本","location":"https://ctext.org/guo-yu/zh","accessedAt":"2026-08-31"},{"label":"《國語》—維基文庫","edition":"韋昭《國語注》本","location":"https://zh.wikisource.org/zh-hant/國語","accessedAt":"2026-08-31"}],"readingAid":{"translation":"周幽王二年，西周王畿境內的涇水、渭水、洛水三大水系流域同時發生強烈大地震（西周三川皆震）。太史伯陽父悲歎道：西周王朝恐怕即將徹底滅亡了！大凡天地自然陰陽之氣，從不失其運行次序；如果錯亂了次序，往往是人間政治混亂所引發的感應！陽氣深伏在地下無法發洩出來，陰氣沉重壓迫無法蒸發升騰，於是就會爆發大地震！如今涇、渭、洛三川同時震動，這是陽氣失去了正常位置而受到陰氣沉重壓抑。陽氣失位陷於陰氣之中，江河的水源就必定會淤塞斷流；水源一旦乾涸枯竭，國家就必定走向滅亡！當年伊水、洛水枯竭而夏朝滅亡，黃河枯竭而商朝滅亡！如今大周王朝的統治道德，已經墮落到同夏、商兩朝末代暴君一模一樣了，如今江河水源又發生堵塞，堵塞之後江河必將枯竭！一個國家必定依託名山大川繁衍生存，大山崩塌、江河乾涸，這正是國家覆亡的致命凶兆啊！如果國家要滅亡絕對超不過十年，因為十年是天道運行的極限週期（數之紀也）。天道所拋棄的政權，壽命絕對超不過一個紀元！就在這一年，涇、渭、洛三川果然全部乾涸枯竭，周人發祥地的岐山發生大崩塌！到了周幽王十一年，申侯聯合犬戎攻破鎬京殺死幽王，西周滅亡，周平王被迫東遷洛邑！","analysis":"【題解與伯陽父論三川皆震西周將亡】本段為中國古代天人感應與環境地質史之千古名篇——伯陽父以「山崩川竭、陽伏陰迫」精闢預言西周十年內必亡，十一年幽王烽火戲諸侯身死國滅！\\\\n【詞義訓詁】「西周三川」：涇水、渭水、洛水；「伯陽父」：周幽王時太史；「伊洛竭夏亡，河竭商亡」：歷代生態環境枯竭與王朝覆滅之歷史總結；「數之紀也」：十年為一紀，預言十年內覆滅；「幽王滅周東遷」：公元前771年西周滅亡。","historicalContext":"","keywords":[]}},{"id":"guo-yu_ch-1_p-18","chapterId":"guo-yu_ch-1","order":18,"canonicalText":"惠王三年，邊伯、石速、蒍國出王而立子頹。王處於鄭三年。王子頹飲三大夫酒，子國為客，樂及遍舞。鄭伯聞之，見虢叔曰：「寡人聞之，哀樂不時，殃咎必至。今王子頹歌舞不倦，樂及遍舞，是忘其憂而玩其殃也。禍必及之，我其納王乎。」虢叔許之。四年春，鄭伯、虢叔奉王以伐京師，殺子頹及五大夫，王乃復位。","sentenceIds":["guo-yu_ch-1_p-18_s-1","guo-yu_ch-1_p-18_s-2","guo-yu_ch-1_p-18_s-3","guo-yu_ch-1_p-18_s-4","guo-yu_ch-1_p-18_s-5","guo-yu_ch-1_p-18_s-6","guo-yu_ch-1_p-18_s-7","guo-yu_ch-1_p-18_s-8"],"sourceRefs":[{"label":"《國語》—中國哲學書電子化計劃","edition":"四部叢刊景宋明道本","location":"https://ctext.org/guo-yu/zh","accessedAt":"2026-08-31"},{"label":"《國語》—維基文庫","edition":"韋昭《國語注》本","location":"https://zh.wikisource.org/zh-hant/國語","accessedAt":"2026-08-31"}],"readingAid":{"translation":"周惠王三年，大夫邊伯、石速、蒍國等人將周惠王驅逐出國都，擁立王子頹為天子。周惠王在鄭國流亡了三年。有一天，王子頹設宴請這三位大夫喝酒，以蒍國（即子國）為主客，宴席上的音樂奏盡了所有種類的舞蹈樂曲。鄭國國君聽說這件事後，去見虢國國君虢叔說：我聽說過這樣的話：悲哀與歡樂如果不符合時宜，災禍就必然會降臨。如今王子頹篡位未穩卻不知疲倦地日夜歌舞，甚至把所有的樂舞都演奏了一遍，這簡直是忘記了國家的憂患而在拿災禍開玩笑啊。大禍一定會降臨到他頭上，我們還是出兵護送惠王回國復位吧。虢叔答應了這個提議。到了周惠王四年的春天，鄭伯與虢叔護送著周惠王討伐京師，殺死了王子頹和那五個叛亂的大夫，周惠王這才重新登上了王位。","analysis":"【訓詁與名物】：「出王」指驅逐國君。「子頹」即王子頹，周莊王之子，曾受寵愛。「飲……酒」指設宴請人喝酒。「遍舞」指將周朝最高規格的六代之樂全部演奏並舞蹈一遍，這在當時是極其僭越的行為。「不時」指不合時宜。「殃咎」指災禍。「玩」指輕視、戲弄。「納王」指護送國君回國復位。「虢叔」即虢國國君，周王室的卿士。\\\\n\\\\n【章法與結構】：這段史料的敘事節奏明快。首句交代了「子頹篡位」的政治大事件；緊接著鏡頭轉向子頹的宮廷宴樂（飲酒遍舞），這是他敗亡的伏筆；隨後通過鄭伯之口進行政治點評（哀樂不時，殃咎必至），並做出了出兵「納王」的戰略決策；最後兩句乾淨利落地交代了討伐叛亂、惠王復位的歷史結局。事件的起因、發展、高潮與結局一氣呵成。\\\\n\\\\n【思想與義理】：此段故事深刻反映了中國古代「禮樂治國」的政治文化傳統。在古人看來，音樂與舞蹈不僅僅是娛樂，更是政治秩序與道德修養的象徵。王子頹篡位後，非但沒有安撫天下、憂慮政權的合法性，反而僭越禮制，大搞「遍舞」這種極致的享樂（哀樂不時），這暴露了他驕奢淫逸、政治上極其幼稚的本質。鄭伯正是從他違背禮樂的舉動中，敏銳地洞察到了他必然滅亡的命運（玩其殃）。這說明在傳統政治邏輯中，個人的道德修養與對禮制的敬畏，直接決定了政權的存亡。","historicalContext":"","keywords":[]}},{"id":"guo-yu_ch-1_p-19","chapterId":"guo-yu_ch-1","order":19,"canonicalText":"十五年，有神降於莘，王問於內史過，曰：「是何故？固有之乎？」對曰：「有之。國之將興，其君齊明、衷正、純潔、惠和，其德足以昭其馨香，其惠足以明其施捨。民思其德，遠神降福，故神降之，觀其政德而賜之福。國之將亡，其君貪冒、辟邪、淫慝、荒怠，其德足以致其怨讟，其政足以殘其民物。民怨其上，妖孽降殃，故神亦降之，觀其苛慝而加之禍。故神降，興亡之兆也。」","sentenceIds":["guo-yu_ch-1_p-19_s-1","guo-yu_ch-1_p-19_s-2","guo-yu_ch-1_p-19_s-3","guo-yu_ch-1_p-19_s-4","guo-yu_ch-1_p-19_s-5","guo-yu_ch-1_p-19_s-6","guo-yu_ch-1_p-19_s-7","guo-yu_ch-1_p-19_s-8","guo-yu_ch-1_p-19_s-9"],"sourceRefs":[{"label":"《國語》—中國哲學書電子化計劃","edition":"四部叢刊景宋明道本","location":"https://ctext.org/guo-yu/zh","accessedAt":"2026-08-31"},{"label":"《國語》—維基文庫","edition":"韋昭《國語注》本","location":"https://zh.wikisource.org/zh-hant/國語","accessedAt":"2026-08-31"}],"readingAid":{"translation":"周惠王十五年，有神明降臨在虢國的莘地（神降於莘），惠王向史官內史過詢問道：這是什麼原因？歷史上真有神明降臨之事嗎？內史過回答說：歷史上確實有這種現象。當一個國家即將興盛崛起之際，其君王必定虔誠明智、內心公正、品行純潔、仁惠溫和，其崇高道德足以向神明散發馨香香氣，其仁惠恩澤足以明察普施於萬民！百姓深切感念他的恩德，遠方的神明也會降下福祉，所以神靈降臨人間，是為了考察他的仁政德行並賜予他無盡福報！反之，當一個國家即將滅亡敗落之際，其君王必定貪婪無厭、偏邪不正、荒淫邪惡、荒廢政事，其敗德足以招致天下百姓的無盡怨恨咒罵，其暴政足以殘害社稷萬物生靈！百姓深切怨恨君上，妖孽降臨人間施加災殃，所以神明此時降臨，是為了考察他的殘暴邪惡並施加滅頂之禍！所以神明降臨，既可能是國家興盛的吉兆，也可能是國家覆亡的凶兆！","analysis":"【題解與內史過論神降於莘興亡之兆】內史過以高度理性主義與政治倫理學解釋「神降於莘」現象——神明的賜福或降禍，完全取決於君王自身的政治修明或殘暴荒淫（德足以昭馨香 vs 德足以致怨讟）！\\\\n【詞義訓詁】「神降於莘」：莘，音深，虢國地名；「齊明衷正」：莊重明智、內心公正；「怨讟」：讟，音讀，怨恨咒罵；「苛慝」：苛刻殘暴之罪惡。\\\\n【神道設教之政治本質】將宗教神異現象轉化為考察統治者道德與民心向背的鏡子，體現了先秦史家借鬼神之說闡揚人間正義之深邃政治智慧。","historicalContext":"","keywords":[]}},{"id":"guo-yu_ch-1_p-20","chapterId":"guo-yu_ch-1","order":20,"canonicalText":"王曰：「今是何神也？」對曰：「昔昭王娶於房，曰房後，實有爽德，協于丹朱，丹朱憑身以儀之，生穆王焉。實為周穆神，今其降於虢，虢公必不免矣。」","sentenceIds":["guo-yu_ch-1_p-20_s-1","guo-yu_ch-1_p-20_s-2","guo-yu_ch-1_p-20_s-3","guo-yu_ch-1_p-20_s-4"],"sourceRefs":[{"label":"《國語》—中國哲學書電子化計劃","edition":"四部叢刊景宋明道本","location":"https://ctext.org/guo-yu/zh","accessedAt":"2026-08-31"},{"label":"《國語》—維基文庫","edition":"韋昭《國語注》本","location":"https://zh.wikisource.org/zh-hant/國語","accessedAt":"2026-08-31"}],"readingAid":{"translation":"周王問道：今天降臨的這到底是哪路神明呢？內史過回答說：從前周昭王在房國娶了妻子，被稱為房後，她確實有著特異的德性，她的精神與堯的兒子丹朱相契合，丹朱的神靈便憑藉著她的身體顯現威儀，從而生下了周穆王。這降臨的神靈實際上就是周朝的穆神（即丹朱的神靈轉世），如今他降臨到虢國，虢國國君恐怕是難以免除災禍了。","analysis":"【訓詁與名物】：「昭王」指周昭王。「房」為古國名。「房後」指昭王之後。「爽德」指特異、明朗的德性，也指不同尋常的特質。「協」指契合、相合。「丹朱」是傳說中堯的兒子，因品行不端未被傳位。「憑身以儀之」指神明依附在人的身體上以顯示其容儀與威嚴。「穆王」即周穆王，傳說中周遊天下的君主。「虢」即虢國。「不免」指不能免於災禍。\\\\n\\\\n【章法與結構】：本段採取了簡單的問答體形式。周王發問直奔主題（何神），內史過的回答則充滿了神話色彩與歷史宿命感。他追溯了周穆王出生的神異傳說，將丹朱的神靈與周朝王室的血脈聯繫在一起，最後落腳於現實的政治預言：神明降臨虢國，預示著虢國即將面臨巨大的災禍（虢公必不免矣）。\\\\n\\\\n【思想與義理】：這段文字反映了春秋時期濃厚的「神降」觀念與天命思想。古人認為，國家的興衰存亡往往伴隨著神明的降臨與預兆。丹朱在歷史傳說中是一個未能繼承大統、帶有悲劇與暴戾色彩的人物，內史過將其視為「穆神」，並認為他降臨虢國是不祥之兆。這種「神道設教」的敘事方式，實際上是古人試圖用超自然的力量來解釋現實政治中諸侯國（如虢國）因統治階級昏庸腐敗而必然走向滅亡的歷史規律，體現了天道與人事相交織的神祕主義政治觀。","historicalContext":"","keywords":[]}},{"id":"guo-yu_ch-1_p-21","chapterId":"guo-yu_ch-1","order":21,"canonicalText":"王曰：「虢其幾何？」對曰：「昔堯臨民以五，今其胄見，神之見也，不過其物。若由是觀之，不過五年，虢必亡矣。」十九年，晉滅虢。","sentenceIds":["guo-yu_ch-1_p-21_s-1","guo-yu_ch-1_p-21_s-2","guo-yu_ch-1_p-21_s-3","guo-yu_ch-1_p-21_s-4"],"sourceRefs":[{"label":"《國語》—中國哲學書電子化計劃","edition":"四部叢刊景宋明道本","location":"https://ctext.org/guo-yu/zh","accessedAt":"2026-08-31"},{"label":"《國語》—維基文庫","edition":"韋昭《國語注》本","location":"https://zh.wikisource.org/zh-hant/國語","accessedAt":"2026-08-31"}],"readingAid":{"translation":"周王又問道：那麼虢國還能存在多久呢？內史過回答說：從前堯帝治理百姓時，以五為基本的數術法則（如五行、五教等），如今他的後裔（丹朱之神）顯現出來，神明的顯現，其預示的時間跨度不會超過他所代表的那個法則數字。如果從這一點來看，不出五年，虢國必定會滅亡。到了周惠王十九年，晉國果然消滅了虢國。","analysis":"【訓詁與名物】：「幾何」指還有多少時間，存活多久。「堯臨民以五」指堯帝治理天下時，常以「五」這個數字作為法度，如五行、五刑、五典等。「胄」指後裔，此指堯的兒子丹朱的神靈。「見」同現，顯現。「不過其物」指神明降臨所預示的時間，不會超過其祖先所崇尚的數字法則（即五）。「十九年」指周惠王十九年（公元前658年）。\\\\n\\\\n【章法與結構】：此段承接上文，繼續以對話形式展開預言。周王關心的是具體的滅亡時間（幾何），內史過的回答則展現了一種奇特的數術邏輯：從堯的「以五臨民」推導出丹朱之神預示的期限「不過五年」，從而得出「虢必亡矣」的鐵斷。最後一句「十九年，晉滅虢」則是史官視角的客觀補敘，以無可辯駁的歷史事實印證了預言的準確性。\\\\n\\\\n【思想與義理】：這段文字生動地展現了古代中國占卜文化中神祕的「象數」思想。內史過通過將歷史人物（堯、丹朱）與特定的數字（五）相結合，來推斷現實政治的走向。這種看似荒誕的神祕主義預言，其背後的實質卻是對虢國君主驕奢淫逸、倒行逆施等現實政治狀況的深刻洞察。預言的準確應驗（晉滅虢），不僅增添了歷史的宿命色彩，也強化了傳統文化中「多行不義必自斃」、「天意不可違」的道德與政治警示意義。","historicalContext":"","keywords":[]}},{"id":"guo-yu_ch-1_p-22","chapterId":"guo-yu_ch-1","order":22,"canonicalText":"襄王使邵公過及內史過賜晉惠公命，呂甥、郤芮相晉侯不敬，晉侯執玉卑，拜不稽首。內史過歸，以告王曰：「晉侯其無後乎！王賜之命而晉侯怠，是怠天命也。呂、郤又相之以不敬，是棄禮也。棄禮無親，怠天無福。晉必有咎。」","sentenceIds":["guo-yu_ch-1_p-22_s-1","guo-yu_ch-1_p-22_s-2","guo-yu_ch-1_p-22_s-3","guo-yu_ch-1_p-22_s-4","guo-yu_ch-1_p-22_s-5","guo-yu_ch-1_p-22_s-6","guo-yu_ch-1_p-22_s-7"],"sourceRefs":[{"label":"《國語》—中國哲學書電子化計劃","edition":"四部叢刊景宋明道本","location":"https://ctext.org/guo-yu/zh","accessedAt":"2026-08-31"},{"label":"《國語》—維基文庫","edition":"韋昭《國語注》本","location":"https://zh.wikisource.org/zh-hant/國語","accessedAt":"2026-08-31"}],"readingAid":{"translation":"周襄王派邵公過和內史過前往晉國，賜予晉惠公正式的諸侯冊命。在舉行儀式時，呂甥和郤芮這兩位大臣作為儐相輔佐晉侯，表現得很不恭敬；晉惠公自己拿著玉圭的姿勢很低，行拜禮時頭也沒有觸地。內史過回到周朝後，把這件事報告給襄王說：晉侯恐怕會沒有後嗣吧！天子賜給他冊命，他卻表現得怠慢，這就是對天命的怠慢。呂甥和郤芮輔助他時又不恭敬，這就是拋棄了禮節。拋棄禮節就無法得到國內外的親附，怠慢天命就無法獲得神明的福佑。晉國必定會遭遇災禍。","analysis":"【訓詁與名物】：「襄王」指周襄王。「賜命」指天子正式冊封諸侯。「相」指在典禮上從旁引導、輔助。「執玉卑」指拿著玉器的位置過低，古代禮節中執玉的高低代表了敬意的深淺。「稽首」是古代最隆重的跪拜禮，頭必須觸地。「無後」指沒有後代繼承君位。「怠」指輕慢。「咎」指災禍。\\\\n\\\\n【章法與結構】：本段敘事極具戲劇張力。前半部分是客觀的動作描寫，通過「相晉侯不敬」、「執玉卑」、「不稽首」三個具體的細節，生動地刻畫了晉惠公君臣傲慢無禮的姿態。後半部分則是內史過的嚴厲評判，他將這些細微的禮儀失當上升到了「怠天命」與「棄禮」的高度，並以此推導出「無後」和「有咎」的政治預言，邏輯嚴密，見微知著。\\\\n\\\\n【思想與義理】：這段記載深刻體現了先秦時代「禮儀即政治」的觀念。在古人看來，禮儀絕非單純的形式，而是內心敬畏與政治秩序的外化。晉惠公君臣在天子使者面前的傲慢，暴露出他們對周天子（天命代表）的蔑視與自身道德修養的缺失。這種「棄禮」與「怠命」的心態，必然會導致他們在內政外交上眾叛親離（無親、無福）。這警示統治者，細節中的驕傲往往是政權敗亡的先兆。","historicalContext":"","keywords":[]}},{"id":"guo-yu_ch-1_p-23","chapterId":"guo-yu_ch-1","order":23,"canonicalText":"「古者，先王既有天下，又崇立上帝、明神而敬事之，於是乎有朝日、夕月以教民事君。諸侯春秋受職，各恭其事，修其禮儀，以相敬肅。今晉侯怠於王命，是蔑天子也。」","sentenceIds":["guo-yu_ch-1_p-23_s-1","guo-yu_ch-1_p-23_s-2","guo-yu_ch-1_p-23_s-3","guo-yu_ch-1_p-23_s-4"],"sourceRefs":[{"label":"《國語》—中國哲學書電子化計劃","edition":"四部叢刊景宋明道本","location":"https://ctext.org/guo-yu/zh","accessedAt":"2026-08-31"},{"label":"《國語》—維基文庫","edition":"韋昭《國語注》本","location":"https://zh.wikisource.org/zh-hant/國語","accessedAt":"2026-08-31"}],"readingAid":{"translation":"在古時候，先王既然已經擁有了天下，還要尊崇並確立對上帝和神明的祭祀，恭敬地侍奉他們，因此纔有了春天早晨祭日、秋天傍晚祭月的儀式，以此來教導百姓如何恭敬地侍奉君主。各國諸侯在春秋兩季來到王廷接受職務與政令，各自恭敬地做好自己的本職工作，修明禮儀，以此來相互保持敬畏與肅穆。如今晉侯對天子賜予的冊命如此怠慢，這完全是在蔑視天子啊。","analysis":"【訓詁與名物】：「先王」指古代的聖王。「崇立」指尊崇並確立祭祀。「上帝、明神」指天上的最高神靈及日月星辰等神明。「朝日」指春天早晨祭祀太陽。「夕月」指秋天傍晚祭祀月亮。「受職」指接受天子分配的職務與政令。「敬肅」指恭敬肅穆。「蔑」指輕視、蔑視。\\\\n\\\\n【章法與結構】：此段是內史過論述「敬天法祖」之禮的延續。開篇以「古者先王」起筆，追溯了祭祀禮儀（朝日、夕月）的起源與教化目的（教民事君）；然後引申到諸侯的臣道（春秋受職、修其禮儀）；最後話鋒一轉，將古人的恭敬與「今晉侯」的怠慢進行強烈對比，得出了「蔑天子也」的結論。借古非今，氣勢磅礡。\\\\n\\\\n【思想與義理】：本段闡述了西周禮樂文化中「神道設教」與「以禮治國」的核心邏輯。先王祭祀日月神明，表面上是敬鬼神，實質上是為了在人間建立一種等級森嚴、充滿敬畏的倫理秩序（教民事君）。諸侯對天子的恭敬，是維持整個天下太平（相敬肅）的基石。晉惠公怠慢王命，破壞的不僅是君臣之禮，更是顛覆了這套維繫天下的根本秩序。這體現了周人對於禮樂制度崩潰的深切憂慮。","historicalContext":"","keywords":[]}},{"id":"guo-yu_ch-1_p-24","chapterId":"guo-yu_ch-1","order":24,"canonicalText":"「夫晉侯非嗣也，而得其位，亹亹怵惕，保任戒懼，猶曰未也。若將廣其心而遠其鄰，陵其民而卑其上，將何以守國？民叛鄰仇，上怒下怨，其何能久？」","sentenceIds":["guo-yu_ch-1_p-24_s-1","guo-yu_ch-1_p-24_s-2","guo-yu_ch-1_p-24_s-3","guo-yu_ch-1_p-24_s-4"],"sourceRefs":[{"label":"《國語》—中國哲學書電子化計劃","edition":"四部叢刊景宋明道本","location":"https://ctext.org/guo-yu/zh","accessedAt":"2026-08-31"},{"label":"《國語》—維基文庫","edition":"韋昭《國語注》本","location":"https://zh.wikisource.org/zh-hant/國語","accessedAt":"2026-08-31"}],"readingAid":{"translation":"何況晉侯（惠公）本來並不是合法的繼承人，卻僥倖得到了國君的寶座，他本應該勤勉小心、時常感到恐懼，戰戰兢兢地保住自己的位置，即使這樣都還怕做的不夠。如果他反而放縱自己的慾望而疏遠鄰國，欺凌國內的百姓而輕視天子，那他將憑什麼來守住這個國家呢？百姓背叛他，鄰國仇視他，天子對他發怒，臣下對他怨恨，這樣的統治又怎麼可能長久呢？","analysis":"【訓詁與名物】：「非嗣」指晉惠公並非原定的合法繼承人（嫡長子），他是通過政治鬥爭和賄賂纔回國即位的。「亹亹（wěi）」指勤勉不倦。「怵惕」指恐懼、警惕。「保任」指保住並承擔責任。「廣其心」指放縱自己的私慾，驕傲自大。「陵」指欺凌。「卑其上」指輕視天子。「其何能久」指怎麼能長久。\\\\n\\\\n【章法與結構】：這段話直指晉惠公的痛處，邏輯層層遞進。首先點出其「非嗣」的尷尬身份，提出他理應具備的態度（亹亹怵惕）；隨後用「若將……將何以……」的假設反問句式，揭露了他驕橫跋扈的真實面目（遠鄰、陵民、卑上）；最後用極其凝練的四字對句「民叛鄰仇，上怒下怨」概括了他四面楚歌的絕境，得出了必然滅亡的結論。說理透徹，令人膽寒。\\\\n\\\\n【思想與義理】：這段分析展現了古代政治家深邃的戰略眼光與政治倫理。一個君主權力的穩固，不能僅靠權謀與僥倖，更需要懷有「戒懼」之心。內史過將治國的要素歸結為四個維度：對上敬畏天子，對下愛護百姓，對外結交鄰國，對內收服人心。晉惠公的傲慢恰恰將這四點破壞殆盡，導致了「上怒、下怨、鄰仇、民叛」的死局。這深刻告誡後人，缺乏合法性與道德約束的統治，越是驕狂，敗亡得越快。","historicalContext":"","keywords":[]}},{"id":"guo-yu_ch-1_p-25","chapterId":"guo-yu_ch-1","order":25,"canonicalText":"「夫執玉卑，替其贄也；拜不稽首，誣其王也。替贄無鎮，誣王無民。夫天事恆象，任重享大者必速及禍。晉侯其不得終矣！」","sentenceIds":["guo-yu_ch-1_p-25_s-1","guo-yu_ch-1_p-25_s-2","guo-yu_ch-1_p-25_s-3","guo-yu_ch-1_p-25_s-4","guo-yu_ch-1_p-25_s-5","guo-yu_ch-1_p-25_s-6"],"sourceRefs":[{"label":"《國語》—中國哲學書電子化計劃","edition":"四部叢刊景宋明道本","location":"https://ctext.org/guo-yu/zh","accessedAt":"2026-08-31"},{"label":"《國語》—維基文庫","edition":"韋昭《國語注》本","location":"https://zh.wikisource.org/zh-hant/國語","accessedAt":"2026-08-31"}],"readingAid":{"translation":"手持玉圭的位置如此低卑，這是廢棄毀壞了代表國家信譽的見面禮節（替其贄）；跪拜行禮時額頭不肯觸地，這是在公然欺瞞蔑視自己的天子君王（誣其王）！廢棄禮信信物就失去了鎮定國家的基石，欺瞞天子君王就失去了統治萬民的民心！天道運行的規律永遠有其對應徵象，身負重任、享受大國厚祿卻品德極端敗壞的人，必定會迅速遭遇滅頂之災！晉惠公將來必定不得善終啊！","analysis":"【題解與替贄無鎮誣王無民必速及禍】本段內史過以「替贄無鎮、誣王無民」八字蓋棺定論，宣告晉惠公在外交禮儀上的失德將直接引發政治合法性崩塌。\\\\n【詞義訓詁】「替贄無鎮」：廢棄信物失去了安定國家的依託；「誣王無民」：欺瞞天子君王必將喪失萬民擁戴；「速及禍」：迅速招致滅頂災難。\\\\n【政治合法性警示】統治者的言行舉止代表國家形象與信用，一旦背棄承諾與法統，政治信用破產後政權將迅速解體。","historicalContext":"","keywords":[]}},{"id":"guo-yu_ch-1_p-26","chapterId":"guo-yu_ch-1","order":26,"canonicalText":"襄王三年而立晉侯，八年而隕於韓，十六年而晉人殺懷公。懷公無胄，秦人殺子金、子公。內史過之言皆驗。","sentenceIds":["guo-yu_ch-1_p-26_s-1","guo-yu_ch-1_p-26_s-2","guo-yu_ch-1_p-26_s-3"],"sourceRefs":[{"label":"《國語》—中國哲學書電子化計劃","edition":"四部叢刊景宋明道本","location":"https://ctext.org/guo-yu/zh","accessedAt":"2026-08-31"},{"label":"《國語》—維基文庫","edition":"韋昭《國語注》本","location":"https://zh.wikisource.org/zh-hant/國語","accessedAt":"2026-08-31"}],"readingAid":{"translation":"在周襄王三年的時候冊立了晉惠公，到了襄王八年的時候，晉惠公在韓原之戰中戰敗並被秦國俘虜，到了襄王十六年的時候，晉國人殺死了晉惠公的兒子晉懷公。晉懷公沒有留下後代，秦國人又殺死了當年輔佐惠公的子金（即呂甥）和子公（即郤芮）。內史過當初所說的預言全部都應驗了。","analysis":"【訓詁與名物】：「襄王三年而立晉侯」指周襄王三年派人賜命晉惠公。「隕於韓」指晉惠公在韓原之戰中被秦穆公擊敗並俘獲，隕在此處有墜落、失敗被擒之意。「殺懷公」指晉文公重耳回國後，晉國人殺死了惠公之子晉懷公。「胄」指後代。「子金」即呂甥的字。「子公」即郤芮的字。「驗」指應驗、證實。\\\\n\\\\n【章法與結構】：這是一段標準的史家補敘。沒有華麗的辭藻，只用冰冷的年份（三年、八年、十六年）和殘酷的歷史事件（隕於韓、殺懷公、無胄、殺子金子公）進行白描。這種將客觀史實與前文內史過的預言（晉必有咎、晉侯無後）進行對照的寫法，構成了強烈的戲劇性閉環，最後以「皆驗」二字收尾，乾脆利落，極具震撼力。\\\\n\\\\n【思想與義理】：這段簡短的史實記錄，是古人「天道好還」、「因果報應」思想的最佳註腳。晉惠公君臣當初在冊命儀式上的不可一世與傲慢無禮，最終換來的是兵敗被俘、子嗣斷絕、身首異處的悲慘下場。歷史的車輪無情地碾碎了傲慢者的野心，證明瞭缺乏敬畏、違背禮教與民心必將走向毀滅的鐵律。這同時也凸顯了內史過作為智者洞燭機先的非凡遠見。","historicalContext":"","keywords":[]}},{"id":"guo-yu_ch-1_p-27","chapterId":"guo-yu_ch-1","order":27,"canonicalText":"襄王使太宰文公及內史興賜晉文公命，上卿逆於境，晉侯郊勞，館諸宗廟，饋九牢，設庭燎。及期命於廟，晉侯拜受，稽首升成。內史興歸，告王曰：「晉侯必霸！其敬禮也周，其接賓也恪，上敬天子，下親百官，霸業必成。」","sentenceIds":["guo-yu_ch-1_p-27_s-1","guo-yu_ch-1_p-27_s-2","guo-yu_ch-1_p-27_s-3","guo-yu_ch-1_p-27_s-4","guo-yu_ch-1_p-27_s-5"],"sourceRefs":[{"label":"《國語》—中國哲學書電子化計劃","edition":"四部叢刊景宋明道本","location":"https://ctext.org/guo-yu/zh","accessedAt":"2026-08-31"},{"label":"《國語》—維基文庫","edition":"韋昭《國語注》本","location":"https://zh.wikisource.org/zh-hant/國語","accessedAt":"2026-08-31"}],"readingAid":{"translation":"後來，周襄王派太宰文公和內史興去賜予晉文公正式的諸侯冊命，晉國的上卿親自到邊境去迎接，晉文公則在國都郊外親自慰勞使者，將他們安頓在宗廟中住宿，並進獻最高規格的太牢九鼎之食，在庭院中點燃盛大的火炬。到了冊命的吉日，在宗廟中舉行儀式，晉侯恭敬地跪拜接受，頭觸地行稽首大禮，然後登上大堂完成儀式。內史興回到周朝後，報告襄王說：晉侯必定能稱霸諸侯！他行禮極其周到，接待賓客極其恭敬，對上敬畏天子，對下親和百官，他的霸業一定會成功。","analysis":"【訓詁與名物】：「太宰」官名，掌管國家政務與祭祀。「晉文公」即重耳，晉國霸主。「逆」指迎接。「郊勞」指在國都郊外慰勞使者，以示尊重。「館」作動詞，安排住宿。「九牢」指九副牛羊豕三牲，是天子賜予上公的最高飲食規格。「庭燎」指在庭院中燃燒的大火炬，為隆重儀式的照明。「拜受、稽首、升成」皆為周朝極為恭敬嚴格的受命禮儀。「周」指周到。「恪」指恭敬。\\\\n\\\\n【章法與結構】：本段在結構上與前文晉惠公受命形成了鮮明而完美的對比。作者同樣採用了先敘事後評論的手法。前半部分詳細鋪陳了晉文公迎接使者的每一個環節（逆於境、郊勞、館宗廟、饋九牢、稽首），無一不合乎最高規格的禮制；後半部分則是內史興的斷言，從具體的「敬禮」推導出「必霸」的宏大預言。前後輝映，主旨鮮明。\\\\n\\\\n【思想與義理】：這段記載通過晉文公與晉惠公的對比，進一步深化了「禮治」與「霸業」的關係。晉文公作為春秋五霸之一，他的成功並非偶然。他深知，在禮崩樂壞的時代，誰能重新尊崇周天子，誰能嚴格遵守傳統的禮儀秩序（敬禮周、接賓恪），誰就能佔據道德與政治的制高點，從而獲得天下諸侯的歸心（必霸）。這種「尊王攘夷」、以禮服人的政治智慧，是晉文公成就千秋霸業的關鍵基石。","historicalContext":"","keywords":[]}},{"id":"guo-yu_ch-1_p-28","chapterId":"guo-yu_ch-1","order":28,"canonicalText":"王從之，使於晉者，道相逮也。及惠後之難，王出在鄭，晉侯納之。尊王攘夷，晉乃大興。","sentenceIds":["guo-yu_ch-1_p-28_s-1","guo-yu_ch-1_p-28_s-2","guo-yu_ch-1_p-28_s-3"],"sourceRefs":[{"label":"《國語》—中國哲學書電子化計劃","edition":"四部叢刊景宋明道本","location":"https://ctext.org/guo-yu/zh","accessedAt":"2026-08-31"},{"label":"《國語》—維基文庫","edition":"韋昭《國語注》本","location":"https://zh.wikisource.org/zh-hant/國語","accessedAt":"2026-08-31"}],"readingAid":{"translation":"周襄王採納了內史興的建議，與晉國建立極其緊密的聯盟關係，洛邑往來於晉國的王室使節絡繹不絕，在道路上車馬相連彼此相望！及至後來王子帶勾結狄人發動叛亂（惠後之難），周襄王被迫出逃避難於鄭國，晉文公果斷起兵平定叛亂、迎奉周天子重返王宮！尊崇周天子王權、抵禦驅逐外圍戎狄夷狄（尊王攘夷），晉國從此大舉繁榮崛起！","analysis":"【題解與晉侯納王尊王攘夷晉乃大興】本段記載晉文公踐行「尊王攘夷」大略，平定王子帶之亂迎襄王復位，牢牢搶佔天下道義制高點。\\\\n【詞義訓詁】「使於晉者道相逮」：王室與晉國外交使節絡繹不絕；「惠後之難」：王子帶勾結狄人發動之王室內亂；「晉侯納之」：晉文公出兵勤王平定叛亂。\\\\n【大戰略智慧】晉文公巧妙將大國軍事實力與王室道義旗幟相結合，既化解了王室危機，又奠定了晉國百年霸業。","historicalContext":"","keywords":[]}},{"id":"guo-yu_ch-1_p-29","chapterId":"guo-yu_ch-1","order":29,"canonicalText":"襄王十六年，立晉文公。二十一年，以諸侯朝王于衡雍，且獻楚捷，遂為踐土之盟，於是乎始霸。此知禮之報也。","sentenceIds":["guo-yu_ch-1_p-29_s-1","guo-yu_ch-1_p-29_s-2","guo-yu_ch-1_p-29_s-3"],"sourceRefs":[{"label":"《國語》—中國哲學書電子化計劃","edition":"四部叢刊景宋明道本","location":"https://ctext.org/guo-yu/zh","accessedAt":"2026-08-31"},{"label":"《國語》—維基文庫","edition":"韋昭《國語注》本","location":"https://zh.wikisource.org/zh-hant/國語","accessedAt":"2026-08-31"}],"readingAid":{"translation":"在周襄王十六年的時候，晉文公被冊立為晉國國君。到了襄王二十一年，晉文公率領各國諸侯在衡雍朝見周天子，並且將城濮之戰中戰勝楚國所繳獲的戰利品獻給天子，隨後便主持了著名的踐土之盟，從此正式開始了他的霸業。這就是他當初懂得並遵守禮儀所得到的回報。","analysis":"【訓詁與名物】：「襄王十六年」指公元前636年。「以」指率領。「朝王」指朝見周天子。「衡雍」地名，在今河南境內。「楚捷」指晉楚城濮之戰後，晉軍繳獲的楚國戰利品與俘虜。「踐土之盟」是晉文公稱霸的標誌性事件，諸侯在踐土會盟，尊晉文公為霸主。「報」指回報、果報。\\\\n\\\\n【章法與結構】：這段文字是史官對晉文公霸業的簡明總結，也是對前文「內史興之言」的歷史印證。它精確地列出了三個時間節點與重大事件：十六年立君、二十一年朝王獻捷、踐土會盟始霸。最後一句「此知禮之報也」畫龍點睛，將宏大的政治軍事勝利，歸結為道德與禮儀修養的必然結果，形成了首尾呼應的閉環。\\\\n\\\\n【思想與義理】：這句話道出了《國語》乃至整個傳統儒家史學的核心價值觀：「禮治」與「因果」。晉文公的霸業（武功），在史家看來，並非僅僅是因為軍事上的強大，更是因為他「知禮」（文治）。他通過「朝王」、「獻捷」等一系列尊王舉動，維護了周天子的權威，從而在道義上折服了天下諸侯。這種將政治上的成功歸因於對禮法秩序的尊重，反映了古人渴望用禮樂文明來規範強權政治的歷史理想。","historicalContext":"","keywords":[]}}],"sentences":[{"id":"guo-yu_ch-1_p-1_s-1","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-1","order":1,"canonicalText":"穆王將徵犬戎，祭公謀父諫曰：「不可。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-1_s-2","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-1","order":2,"canonicalText":"先王耀德不觀兵。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-1_s-3","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-1","order":3,"canonicalText":"夫兵戢而時動，動則威，觀則玩，玩則無震。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-1_s-4","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-1","order":4,"canonicalText":"是故先王之於民也，懋帥其德而廣其振宿，料其動意而政之以禮。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-1_s-5","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-1","order":5,"canonicalText":"發祥明義，以顯道而遏淫慝，是故先王無不聽，無遠不思，無不順，無不從。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-1_s-6","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-1","order":6,"canonicalText":"」","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-2_s-1","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-2","order":1,"canonicalText":"「昔我先王世后稷，以服事虞、夏。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-2_s-2","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-2","order":2,"canonicalText":"及夏之衰也，棄稷不務，我先王不窋用失其官，而自竄於戎、狄之間，不敢怠業，時序其德，纂修其緒，修其訓典，朝夕恪勤，守以敦篤，奉以忠信。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-2_s-3","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-2","order":3,"canonicalText":"奕世載德，不忝前人。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-2_s-4","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-2","order":4,"canonicalText":"」","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-3_s-1","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-3","order":1,"canonicalText":"「夫先王之制：邦內甸服，邦外侯服，侯、衛賓服，蠻、夷要服，戎、狄荒服。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-3_s-2","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-3","order":2,"canonicalText":"甸服者祭，侯服者祀，賓服者享，要服者貢，荒服者王。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-3_s-3","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-3","order":3,"canonicalText":"日祭、月祀、時享、歲貢、終王，先王之訓也。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-3_s-4","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-3","order":4,"canonicalText":"有不祭則修意，有不祀則修言，有不享則修文，有不貢則脩名，有不王則修德，序成而有不至則修刑。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-3_s-5","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-3","order":5,"canonicalText":"」","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-4_s-1","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-4","order":1,"canonicalText":"「今自大畢、伯士之終也，犬戎氏以其職來王。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-4_s-2","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-4","order":2,"canonicalText":"天子曰：『予必以不享徵之，且觀之兵。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-4_s-3","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-4","order":3,"canonicalText":"』其無乃廢先王之訓，而王幾頓乎！","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-4_s-4","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-4","order":4,"canonicalText":"吾聞犬戎樹惇，能帥舊德，而守終純固，其有以禦我矣。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-4_s-5","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-4","order":5,"canonicalText":"」穆王不聽，遂徵之，得四白狼、四白鹿以歸。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-4_s-6","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-4","order":6,"canonicalText":"自是，荒服者不至。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-5_s-1","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-5","order":1,"canonicalText":"恭王遊於涇上，密康公從，有三女奔之。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-5_s-2","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-5","order":2,"canonicalText":"其母曰：「必致之於王。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-5_s-3","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-5","order":3,"canonicalText":"夫獸三為羣，人三為眾，女三為粲。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-5_s-4","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-5","order":4,"canonicalText":"王田不取羣，公行不下眾，王御不參一族。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-5_s-5","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-5","order":5,"canonicalText":"夫粲，美之物也。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-5_s-6","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-5","order":6,"canonicalText":"眾以美物歸女，而何德以堪之？","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-5_s-7","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-5","order":7,"canonicalText":"王猶不堪，況爾之小醜乎！","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-5_s-8","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-5","order":8,"canonicalText":"小醜備物，終必亡。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-5_s-9","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-5","order":9,"canonicalText":"」康公不獻，王滅密。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-6_s-1","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-6","order":1,"canonicalText":"厲王虐，國人謗王。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-6_s-2","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-6","order":2,"canonicalText":"邵公告曰：「民不堪命矣！","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-6_s-3","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-6","order":3,"canonicalText":"」王怒，得衛巫，使監謗者，以告，則殺之。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-6_s-4","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-6","order":4,"canonicalText":"國人莫敢言，道路以目。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-6_s-5","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-6","order":5,"canonicalText":"王喜，告邵公曰：「吾能弭謗矣，乃不敢言。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-6_s-6","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-6","order":6,"canonicalText":"」邵公曰：「是障之也。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-6_s-7","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-6","order":7,"canonicalText":"防民之口，甚於防川。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-6_s-8","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-6","order":8,"canonicalText":"川壅而潰，傷人必多，民亦如之。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-6_s-9","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-6","order":9,"canonicalText":"是故為川者決之使導，為民者宣之使言。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-6_s-10","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-6","order":10,"canonicalText":"」","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-7_s-1","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-7","order":1,"canonicalText":"厲王說榮夷公，芮良夫曰：「王室其將卑乎！","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-7_s-2","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-7","order":2,"canonicalText":"夫榮公好專利而不知大難。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-7_s-3","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-7","order":3,"canonicalText":"夫利，百物之所生也，天地之所載也，而或專之，其害多矣。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-7_s-4","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-7","order":4,"canonicalText":"天地百物皆將取焉，胡可專也？","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-7_s-5","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-7","order":5,"canonicalText":"所利大，其謀亦大；","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-7_s-6","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-7","order":6,"canonicalText":"所害多，其怨亦多。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-7_s-7","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-7","order":7,"canonicalText":"匹夫專利，猶謂之盜，王而若然，其何以庇天下？","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-7_s-8","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-7","order":8,"canonicalText":"」","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-8_s-1","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-8","order":1,"canonicalText":"彘之亂，宣王在邵公之宮，國人圍之，邵公曰：「昔吾驟諫王，王不從，是以及此難。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-8_s-2","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-8","order":2,"canonicalText":"今殺王子，王其以我為妒而報怨乎？","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-8_s-3","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-8","order":3,"canonicalText":"夫事君者，險而不讎，憂而不怨，況事王乎！","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-8_s-4","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-8","order":4,"canonicalText":"」乃以其子代宣王，宣王得以免。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-9_s-1","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-9","order":1,"canonicalText":"宣王即位，不籍千畝。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-9_s-2","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-9","order":2,"canonicalText":"虢文公諫曰：「不可。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-9_s-3","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-9","order":3,"canonicalText":"夫民之大事在農，上帝之粢盛於是乎出，民之蕃庶於是乎生，事神保民，莫大於農。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-9_s-4","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-9","order":4,"canonicalText":"故古者先王必藉千畝，以身帥之，天子親耕，以昭大物也。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-9_s-5","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-9","order":5,"canonicalText":"」","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-10_s-1","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-10","order":1,"canonicalText":"「先時九日，太史告稷曰：『自今至於初吉，陽氣俱蒸，土膏其動。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-10_s-2","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-10","order":2,"canonicalText":"弗震弗渝，脈其滿眚，穀乃不殖。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-10_s-3","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-10","order":3,"canonicalText":"』稷以告王，王乃命司空、司徒，以時修農，敬承天道。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-10_s-4","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-10","order":4,"canonicalText":"」","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-11_s-1","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-11","order":1,"canonicalText":"「先時五日，瞽告有協風至，王即齋宮，百官御事，各即其齋三日。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-11_s-2","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-11","order":2,"canonicalText":"王乃淳濯饗醴，及期，鬱人薦鬯，宗祝贊祀，王親執耒耜，三推而反。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-11_s-3","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-11","order":3,"canonicalText":"」","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-12_s-1","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-12","order":1,"canonicalText":"「是日也，瞽帥、音官以風土。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-12_s-2","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-12","order":2,"canonicalText":"廩於籍東南，鍾而藏之，而時布之於農。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-12_s-3","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-12","order":3,"canonicalText":"稷則遍誡百姓，紀農協功，曰：『敬之哉，無或怠荒！","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-12_s-4","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-12","order":4,"canonicalText":"』」","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-13_s-1","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-13","order":1,"canonicalText":"「是時也，王事唯農是務，無有求利於其官，以幹農功，三時務農而一時講武，故徵則有威，守則有財。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-13_s-2","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-13","order":2,"canonicalText":"今王廢之，是棄本也。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-13_s-3","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-13","order":3,"canonicalText":"」宣王不聽。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-14_s-1","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-14","order":1,"canonicalText":"魯武公以括與戲見王，王立戲，樊仲山父諫曰：「不可立也！","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-14_s-2","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-14","order":2,"canonicalText":"不順必犯，犯王命必誅，故出令不可不順也。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-14_s-3","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-14","order":3,"canonicalText":"先王之立嗣也，必以長以賢。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-14_s-4","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-14","order":4,"canonicalText":"今廢長立幼，是教民不順也。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-14_s-5","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-14","order":5,"canonicalText":"若立戲，諸侯必仿而亂之。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-14_s-6","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-14","order":6,"canonicalText":"」宣王不聽，卒立戲。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-15_s-1","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-15","order":1,"canonicalText":"三十二年春，宣王伐魯，立孝公，諸侯從是而不睦。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-15_s-2","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-15","order":2,"canonicalText":"宣王欲得國子之能導訓諸侯者，樊穆仲曰：「魯侯孝公敬事神明，惠愛百姓，能修舊業，其可使訓導諸侯乎。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-15_s-3","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-15","order":3,"canonicalText":"」王乃使魯侯導諸侯。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-16_s-1","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-16","order":1,"canonicalText":"宣王既喪南國之師，乃料民於太原。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-16_s-2","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-16","order":2,"canonicalText":"仲山父諫曰：「民不可料也！","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-16_s-3","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-16","order":3,"canonicalText":"夫古者不料民而知其少多，司民協孤，司商協質，司寇協獄，司土協田，各守其職，則戶口之數自明。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-16_s-4","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-16","order":4,"canonicalText":"今料民於太原，是暴其寡也，且擾民生怨，不可為也。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-16_s-5","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-16","order":5,"canonicalText":"」宣王不聽，卒料之。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-17_s-1","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-17","order":1,"canonicalText":"幽王二年，西周三川皆震。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-17_s-2","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-17","order":2,"canonicalText":"伯陽父曰：「周將亡矣！","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-17_s-3","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-17","order":3,"canonicalText":"夫天地之氣，不失其序；","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-17_s-4","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-17","order":4,"canonicalText":"若過其序，民亂之也。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-17_s-5","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-17","order":5,"canonicalText":"陽伏而不能出，陰迫而不能蒸，於是有地震。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-17_s-6","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-17","order":6,"canonicalText":"今三川皆震，是陽失其所而鎮陰也。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-17_s-7","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-17","order":7,"canonicalText":"陽失而在陰，川源必塞；","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-17_s-8","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-17","order":8,"canonicalText":"源塞，國必亡。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-17_s-9","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-17","order":9,"canonicalText":"昔伊、洛竭而夏亡，河竭而商亡。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-17_s-10","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-17","order":10,"canonicalText":"今周德如二代之季矣，其川源又塞，塞必竭。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-17_s-11","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-17","order":11,"canonicalText":"夫國必依山川，山崩川竭，亡之徵也。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-17_s-12","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-17","order":12,"canonicalText":"若國亡不過十年，數之紀也。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-17_s-13","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-17","order":13,"canonicalText":"天之所棄，不過其紀。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-17_s-14","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-17","order":14,"canonicalText":"」是歲也，三川竭，岐山崩。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-17_s-15","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-17","order":15,"canonicalText":"十一年，幽王乃滅，周乃東遷。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-18_s-1","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-18","order":1,"canonicalText":"惠王三年，邊伯、石速、蒍國出王而立子頹。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-18_s-2","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-18","order":2,"canonicalText":"王處於鄭三年。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-18_s-3","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-18","order":3,"canonicalText":"王子頹飲三大夫酒，子國為客，樂及遍舞。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-18_s-4","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-18","order":4,"canonicalText":"鄭伯聞之，見虢叔曰：「寡人聞之，哀樂不時，殃咎必至。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-18_s-5","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-18","order":5,"canonicalText":"今王子頹歌舞不倦，樂及遍舞，是忘其憂而玩其殃也。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-18_s-6","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-18","order":6,"canonicalText":"禍必及之，我其納王乎。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-18_s-7","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-18","order":7,"canonicalText":"」虢叔許之。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-18_s-8","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-18","order":8,"canonicalText":"四年春，鄭伯、虢叔奉王以伐京師，殺子頹及五大夫，王乃復位。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-19_s-1","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-19","order":1,"canonicalText":"十五年，有神降於莘，王問於內史過，曰：「是何故？","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-19_s-2","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-19","order":2,"canonicalText":"固有之乎？","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-19_s-3","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-19","order":3,"canonicalText":"」對曰：「有之。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-19_s-4","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-19","order":4,"canonicalText":"國之將興，其君齊明、衷正、純潔、惠和，其德足以昭其馨香，其惠足以明其施捨。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-19_s-5","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-19","order":5,"canonicalText":"民思其德，遠神降福，故神降之，觀其政德而賜之福。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-19_s-6","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-19","order":6,"canonicalText":"國之將亡，其君貪冒、辟邪、淫慝、荒怠，其德足以致其怨讟，其政足以殘其民物。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-19_s-7","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-19","order":7,"canonicalText":"民怨其上，妖孽降殃，故神亦降之，觀其苛慝而加之禍。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-19_s-8","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-19","order":8,"canonicalText":"故神降，興亡之兆也。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-19_s-9","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-19","order":9,"canonicalText":"」","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-20_s-1","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-20","order":1,"canonicalText":"王曰：「今是何神也？","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-20_s-2","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-20","order":2,"canonicalText":"」對曰：「昔昭王娶於房，曰房後，實有爽德，協于丹朱，丹朱憑身以儀之，生穆王焉。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-20_s-3","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-20","order":3,"canonicalText":"實為周穆神，今其降於虢，虢公必不免矣。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-20_s-4","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-20","order":4,"canonicalText":"」","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-21_s-1","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-21","order":1,"canonicalText":"王曰：「虢其幾何？","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-21_s-2","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-21","order":2,"canonicalText":"」對曰：「昔堯臨民以五，今其胄見，神之見也，不過其物。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-21_s-3","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-21","order":3,"canonicalText":"若由是觀之，不過五年，虢必亡矣。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-21_s-4","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-21","order":4,"canonicalText":"」十九年，晉滅虢。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-22_s-1","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-22","order":1,"canonicalText":"襄王使邵公過及內史過賜晉惠公命，呂甥、郤芮相晉侯不敬，晉侯執玉卑，拜不稽首。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-22_s-2","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-22","order":2,"canonicalText":"內史過歸，以告王曰：「晉侯其無後乎！","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-22_s-3","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-22","order":3,"canonicalText":"王賜之命而晉侯怠，是怠天命也。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-22_s-4","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-22","order":4,"canonicalText":"呂、郤又相之以不敬，是棄禮也。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-22_s-5","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-22","order":5,"canonicalText":"棄禮無親，怠天無福。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-22_s-6","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-22","order":6,"canonicalText":"晉必有咎。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-22_s-7","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-22","order":7,"canonicalText":"」","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-23_s-1","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-23","order":1,"canonicalText":"「古者，先王既有天下，又崇立上帝、明神而敬事之，於是乎有朝日、夕月以教民事君。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-23_s-2","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-23","order":2,"canonicalText":"諸侯春秋受職，各恭其事，修其禮儀，以相敬肅。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-23_s-3","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-23","order":3,"canonicalText":"今晉侯怠於王命，是蔑天子也。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-23_s-4","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-23","order":4,"canonicalText":"」","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-24_s-1","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-24","order":1,"canonicalText":"「夫晉侯非嗣也，而得其位，亹亹怵惕，保任戒懼，猶曰未也。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-24_s-2","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-24","order":2,"canonicalText":"若將廣其心而遠其鄰，陵其民而卑其上，將何以守國？","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-24_s-3","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-24","order":3,"canonicalText":"民叛鄰仇，上怒下怨，其何能久？","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-24_s-4","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-24","order":4,"canonicalText":"」","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-25_s-1","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-25","order":1,"canonicalText":"「夫執玉卑，替其贄也；","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-25_s-2","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-25","order":2,"canonicalText":"拜不稽首，誣其王也。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-25_s-3","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-25","order":3,"canonicalText":"替贄無鎮，誣王無民。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-25_s-4","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-25","order":4,"canonicalText":"夫天事恆象，任重享大者必速及禍。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-25_s-5","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-25","order":5,"canonicalText":"晉侯其不得終矣！","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-25_s-6","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-25","order":6,"canonicalText":"」","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-26_s-1","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-26","order":1,"canonicalText":"襄王三年而立晉侯，八年而隕於韓，十六年而晉人殺懷公。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-26_s-2","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-26","order":2,"canonicalText":"懷公無胄，秦人殺子金、子公。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-26_s-3","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-26","order":3,"canonicalText":"內史過之言皆驗。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-27_s-1","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-27","order":1,"canonicalText":"襄王使太宰文公及內史興賜晉文公命，上卿逆於境，晉侯郊勞，館諸宗廟，饋九牢，設庭燎。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-27_s-2","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-27","order":2,"canonicalText":"及期命於廟，晉侯拜受，稽首升成。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-27_s-3","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-27","order":3,"canonicalText":"內史興歸，告王曰：「晉侯必霸！","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-27_s-4","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-27","order":4,"canonicalText":"其敬禮也周，其接賓也恪，上敬天子，下親百官，霸業必成。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-27_s-5","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-27","order":5,"canonicalText":"」","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-28_s-1","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-28","order":1,"canonicalText":"王從之，使於晉者，道相逮也。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-28_s-2","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-28","order":2,"canonicalText":"及惠後之難，王出在鄭，晉侯納之。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-28_s-3","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-28","order":3,"canonicalText":"尊王攘夷，晉乃大興。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-29_s-1","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-29","order":1,"canonicalText":"襄王十六年，立晉文公。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-29_s-2","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-29","order":2,"canonicalText":"二十一年，以諸侯朝王于衡雍，且獻楚捷，遂為踐土之盟，於是乎始霸。","chunks":[],"tags":[]},{"id":"guo-yu_ch-1_p-29_s-3","workId":"guo-yu","chapterId":"guo-yu_ch-1","passageId":"guo-yu_ch-1_p-29","order":3,"canonicalText":"此知禮之報也。","chunks":[],"tags":[]}]}');export{u as default};
